def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # The 2-colored straight border indicates the direction of travel.
    border_cells = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 2]
    rows = {r for r, c in border_cells}
    cols = {c for r, c in border_cells}
    vertical = len(cols) == 1
    border = next(iter(cols)) if vertical else next(iter(rows))

    bg = max(set(x for row in grid for x in row), key=lambda x: sum(row.count(x) for row in grid))
    pts = [(r, c) for r in range(h) for c in range(w)
           if grid[r][c] != bg and grid[r][c] != 2]
    if not pts:
        return out

    if vertical:
        toward = 1 if border > w // 2 else -1
        edge = max(c for r, c in pts) if toward == 1 else min(c for r, c in pts)
        shift = (border - 1 - edge) if toward == 1 else (border + 1 - edge)
        # Move the object as far as possible toward the border.
        for r, c in pts:
            out[r][c] = bg
        moved = [(r, c + shift) for r, c in pts]
        for r, c in moved:
            out[r][c] = grid[r][c - shift]
        trail = (min(c for r, c in moved) - 1) if toward == 1 else (max(c for r, c in moved) + 1)
        if 0 <= trail < w:
            for r in range(h):
                out[r][trail] = 8
    else:
        toward = 1 if border > h // 2 else -1
        edge = max(r for r, c in pts) if toward == 1 else min(r for r, c in pts)
        shift = (border - 1 - edge) if toward == 1 else (border + 1 - edge)
        for r, c in pts:
            out[r][c] = bg
        moved = [(r + shift, c) for r, c in pts]
        for r, c in moved:
            out[r][c] = grid[r - shift][c]
        trail = (min(r for r, c in moved) - 1) if toward == 1 else (max(r for r, c in moved) + 1)
        if 0 <= trail < h:
            for c in range(w):
                out[trail][c] = 8
    return out
